{
    uint32_t sum = 0;
    int i;

    for (i = seq; i < seq + len; i++) {
        if (i & 1) {
            sum += (uint32_t)buf[i - seq];
        } else {
            sum += (uint32_t)buf[i - seq] << 8;
        }
    }
    return sum;
}

uint16_t net_checksum_tcpudp(uint16_t length, uint16_t proto, /* <=== net_checksum_tcpudp */ 
                             uint8_t *addrs, uint8_t *buf)
{
